/* Firm reason2: metadata transcript + native admission/publication ABI oracle.
   No learned matrix, activation or model execution takes place on the CPU. */
#include "action-plan.h"
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static size_t cases;
static void str(FILE*f,coax_string s){fprintf(f,"%lld:",(long long)s.count);assert(fwrite(s.data,1,(size_t)s.count,f)==(size_t)s.count);}
static void abi(void){int64_t ids[140]={0};uint8_t text[141],image[141];memset(text,9,sizeof text);memset(image,9,sizeof image);ids[4]=151655;assert(gac_masks((coax_v_s64){ids,140},(coax_v_u8){text,140},(coax_v_u8){image,140},0)==0);for(int i=0;i<140;i++){assert(image[i]==(i==4)&&text[i]==(i!=4));cases++;}assert(text[140]==9&&image[140]==9);
 for(int field=0;field<6;field++){memset(text,9,sizeof text);memset(image,9,sizeof image);int64_t ni=140,nt=140,nm=140;int overlap=0;ids[139]=0;if(field==0)ni--;if(field==1)nt--;if(field==2)nm--;if(field==3)overlap=1;if(field==4)ids[139]=-1;if(field==5)ids[139]=151936;assert(gac_masks((coax_v_s64){ids,ni},(coax_v_u8){text,nt},(coax_v_u8){image,nm},overlap)!=0);for(int j=0;j<141;j++)assert(text[j]==9&&image[j]==9);cases++;}
 uint32_t input[5280]={0};float output[5281];for(int i=0;i<5281;i++)output[i]=7;for(int field=0;field<9;field++){coax_t_GvpCursor cursor={.stage=142};int64_t ns=1,ni=5280,no=5280;int overlap=0;if(field==0)ns=0;if(field==1)cursor.status=COAX_GvpStatus_device;if(field==2)cursor.stage=141;if(field==3)cursor.node=1;if(field==4)ni--;if(field==5)no--;if(field==6)overlap=1;if(field==7)input[0]=0x7f800000;if(field==8)input[5279]=0x7fc00001;coax_t_GvpRead r=gac_publish((coax_v_t_GvpCursor){&cursor,ns},(coax_v_u32){input,ni},(coax_v_f32){output,no},overlap);assert(r.status&&r.written==0);for(int j=0;j<5281;j++)assert(output[j]==7);input[0]=input[5279]=0;cases++;}
 coax_t_GvpCursor cursor={.stage=142};input[0]=0x80000000;input[5279]=0x3f800000;coax_t_GvpRead r=gac_publish((coax_v_t_GvpCursor){&cursor,1},(coax_v_u32){input,5280},(coax_v_f32){output,5281},0);assert(!r.status&&r.written==5280&&cursor.stage==143&&output[5279]==1&&output[5280]==7);uint32_t bits;memcpy(&bits,output,4);assert(bits==0x80000000);cases++;
}
int main(int argc,char**argv){assert(argc==2);FILE*f=fopen(argv[1],"wx");assert(f);fprintf(f,"inventory %lld %lld %lld %lld\n",(long long)gac_weight_count(),(long long)gac_buffer_count(),(long long)gac_kernel_count(),(long long)gac_stage_count());for(int i=0;i<537;i++){coax_t_GacSpec s=gac_spec(i);assert(s.ok);fprintf(f,"weight%d ",i);str(f,s.prefix);str(f,s.suffix);fprintf(f," %lld %lld %lld %d %d %d %lld %lld %lld",(long long)s.rank,(long long)s.rows,(long long)s.cols,s.category,s.transpose,s.decode,(long long)s.bytes,(long long)s.take,(long long)s.target);for(int d=0;d<5;d++)fprintf(f," %lld",(long long)s.dims.e[d]);fputc('\n',f);cases++;}
 for(int i=0;i<568;i++)fprintf(f,"buffer%d %lld\n",i,(long long)gac_buffer_bytes(i));for(int i=0;i<12;i++){coax_t_GvpKernel k=gac_kernel(i);fprintf(f,"kernel%d %lld ",i,(long long)k.library);str(f,k.name);fputc('\n',f);}
 for(int stage=0;stage<142;stage++){coax_t_GacStage s=gac_stage(stage);assert(!s.status);fprintf(f,"stage%d %lld %lld %lld %lld %lld\n",stage,(long long)s.kind,(long long)s.step,(long long)s.layer,(long long)s.nodes,(long long)s.flags);int64_t offset=0;for(int at=0;at<s.nodes;at++){coax_t_GvpNode n=gac_node(stage,at);assert(!n.status&&n.flag_offset==offset);offset+=n.flag_count;fprintf(f,"node%d %lld %lld %lld %lld %lld %lld %lld",at,(long long)n.kernel,(long long)n.items,(long long)n.lanes,(long long)n.block,(long long)n.argc,(long long)n.flag_count,(long long)n.flag_offset);for(int a=0;a<n.argc;a++){coax_t_GvpArg v=n.args.e[a];fprintf(f," |%lld %lld %lld %lld %lld %a",(long long)v.kind,(long long)v.integer,(long long)v.buffer,(long long)v.count,(long long)v.offset,v.real);}fputc('\n',f);cases++;}assert(offset==s.flags);for(int slot=0;slot<3;slot++){coax_t_GacCapture c=gac_capture(stage,slot);if(c.ok){fprintf(f,"capture%d ",slot);str(f,c.name);fprintf(f," %lld %lld %lld\n",(long long)c.buffer,(long long)c.count,(long long)c.offset);}}}
 assert(!fclose(f));abi();printf("GR00T action metadata: %zu exact graph/ABI cases passed\n",cases);return 0;}
